    public interface XmppBuilders {
        /**
         * XMPP (camel-xmpp)
         * Send and receive XMPP (Jabber) messages, in private chats and in
         * multi-user chat rooms.
         * 
         * Category: chat,messaging
         * Since: 1.0
         * Maven coordinates: org.apache.camel:camel-xmpp
         * 
         * @return the dsl builder for the headers' name.
         */
        default XmppHeaderNameBuilder xmpp() {
            return XmppHeaderNameBuilder.INSTANCE;
        }
        /**
         * XMPP (camel-xmpp)
         * Send and receive XMPP (Jabber) messages, in private chats and in
         * multi-user chat rooms.
         * 
         * Category: chat,messaging
         * Since: 1.0
         * Maven coordinates: org.apache.camel:camel-xmpp
         * 
         * Syntax: <code>xmpp:host:port/participant</code>
         * 
         * Path parameter: host (required)
         * The host name or IP address of the XMPP server. It is also the XMPP
         * domain when the serviceName option is not set. Not used when the
         * connectionConfig option is set.
         * 
         * Path parameter: port
         * The TCP port of the XMPP server for client connections. Not used when
         * the connectionConfig option is set.
         * Default value: 5222
         * 
         * Path parameter: participant
         * The JID (Jabber ID) of the person to chat with: the producer sends
         * the chat messages to it, and the consumer routes only the chat
         * messages from it (or of every sender, without a participant). The
         * consumer adds the XMPP domain of the server to a name without a
         * domain, while the producer needs the full JID. The room option takes
         * precedence over this option.
         * 
         * @param path host:port/participant
         * @return the dsl builder
         */
        default XmppEndpointBuilder xmpp(String path) {
            return XmppEndpointBuilderFactory.endpointBuilder("xmpp", path);
        }
        /**
         * XMPP (camel-xmpp)
         * Send and receive XMPP (Jabber) messages, in private chats and in
         * multi-user chat rooms.
         * 
         * Category: chat,messaging
         * Since: 1.0
         * Maven coordinates: org.apache.camel:camel-xmpp
         * 
         * Syntax: <code>xmpp:host:port/participant</code>
         * 
         * Path parameter: host (required)
         * The host name or IP address of the XMPP server. It is also the XMPP
         * domain when the serviceName option is not set. Not used when the
         * connectionConfig option is set.
         * 
         * Path parameter: port
         * The TCP port of the XMPP server for client connections. Not used when
         * the connectionConfig option is set.
         * Default value: 5222
         * 
         * Path parameter: participant
         * The JID (Jabber ID) of the person to chat with: the producer sends
         * the chat messages to it, and the consumer routes only the chat
         * messages from it (or of every sender, without a participant). The
         * consumer adds the XMPP domain of the server to a name without a
         * domain, while the producer needs the full JID. The room option takes
         * precedence over this option.
         * 
         * @param componentName to use a custom component name for the endpoint
         * instead of the default name
         * @param path host:port/participant
         * @return the dsl builder
         */
        default XmppEndpointBuilder xmpp(String componentName, String path) {
            return XmppEndpointBuilderFactory.endpointBuilder(componentName, path);
        }

    }
    /**
     * The builder of headers' name for the XMPP component.
     */
    public static class XmppHeaderNameBuilder {
        /**
         * The internal instance of the builder used to access to all the
         * methods representing the name of headers.
         */
        public static final XmppHeaderNameBuilder INSTANCE = new XmppHeaderNameBuilder();

        /**
         * The received Smack message, set by the consumer when the doc option
         * is true. The pubsub producer sets it to the PubSub packet that it
         * sends.
         * 
         * The option is a: {@code org.jivesoftware.smack.packet.Message} type.
         * 
         * Group: consumer
         * 
         * @return the name of the header {@code XmppDoc}.
         */
        public String xmppDoc() {
            return "CamelXmppDoc";
        }
    }
    static XmppEndpointBuilder endpointBuilder(String componentName, String path) {
        class XmppEndpointBuilderImpl extends AbstractEndpointBuilder implements XmppEndpointBuilder, AdvancedXmppEndpointBuilder {
            public XmppEndpointBuilderImpl(String path) {
                super(componentName, path);
            }
        }
        return new XmppEndpointBuilderImpl(path);
    }
